 public static bool Done;public static int Code;public string Root;string mode;CombatSession s;readonly List<Row> rows=new List<Row>();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(!Environment.GetCommandLineArgs().Contains("-c1-probe"))return;var g=new GameObject("C1 isolated runtime probe");DontDestroyOnLoad(g);g.AddComponent<C1Probe>();}
 public void Check(string name,bool value,string detail=""){rows.Add(new Row{name=name,status=value?"PASS":"FAIL",detail=detail});File.AppendAllText(Root+"/progress.jsonl",JsonUtility.ToJson(rows.Last())+"\n");}
