 IEnumerator Start(){Root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);mode=Environment.GetEnvironmentVariable("C1_MODE")??"explore";var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-c1-mode");if(i>=0)mode=args[i+1];Application.runInBackground=true;var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool next;object value=null;try{next=stack.Peek().MoveNext();if(next)value=stack.Peek().Current;}catch(Exception e){Finish(e.ToString());yield break;}if(!next){stack.Pop();continue;}if(value is IEnumerator sub){stack.Push(sub);continue;}yield return value;}Finish(null);}
