 IEnumerator Depart(){var clock=System.Diagnostics.Stopwatch.StartNew();bool departed=s.Flow.DepartRuins();Check("actual-camp-departure",departed,s.Flow.Error+" / "+s.hero.Inventory.Notifications.Text);if(!departed)throw new Exception("Departure rollback: "+s.hero.Inventory.Notifications.Text);yield return Wait(()=>s.WorldReady&&s.Flow.ActiveRun!=null,20);clock.Stop();if(!s.WorldReady)throw new Exception("No ready ruins: "+s.Flow.Error);Check("zone-count",s.GetComponent<ForestRegionRuntime>().Layout.points.Length==RuinsLayout.DefaultStage);Check("run-map-bound",s.Flow.ActiveRun.region==RuinsLayout.Region&&s.Flow.ActiveRun.contentRevision==RuinsLayout.Content&&s.Flow.ActiveRun.generationVersion==9);Check("forest-supplement-not-retagged",!NewWeaponDrop.KnownRevision(s.Flow.ActiveRun.contentRevision));var root=s.GetComponent<ForestRegionRuntime>().PresentationRoot;File.WriteAllText(Root+"/scene-metrics.json",JsonUtility.ToJson(new Metric{status="MEASURED_COUNTS",scope="Actual scene counts and synchronous departure; CPU/GPU/DrawCalls/GC performance NOT_RUN",objects=root.GetComponentsInChildren<Transform>(true).Length,colliders=root.GetComponentsInChildren<Collider>(true).Length,enemies=s.enemies.Length,materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().Count(),departureMilliseconds=clock.Elapsed.TotalMilliseconds},true));}
 void Trace(string stage,string target="",float before=0,float after=0,Vector3 from=default,Vector3 to=default){File.AppendAllText(Root+"/runtime-trace.jsonl",JsonUtility.ToJson(new RuntimeTrace{stage=stage,target=target,mode=mode,position=s.hero.transform.position,time=Time.time,frame=Time.frameCount,before=before,after=after,from=from,to=to})+"\n");}
 IEnumerator Go(Vector3 goal,float max=35){var region=s.GetComponent<ForestRegionRuntime>();var path=new NavMeshPath();if(!NavMesh.SamplePosition(goal,out var end,2,NavMesh.AllAreas)||!NavMesh.SamplePosition(s.hero.transform.position,out var start,2,NavMesh.AllAreas)||!NavMesh.CalculatePath(start.position,end.position,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)throw new Exception("Actual path unavailable: "+goal);File.AppendAllText(Root+"/path-corners.jsonl",JsonUtility.ToJson(new PathRecord{goal=goal,corners=path.corners})+"\n");int corner=1;float until=Time.realtimeSinceStartup+max;while(Vector3.ProjectOnPlane(s.hero.transform.position-end.position,Vector3.up).magnitude>.45f&&Time.realtimeSinceStartup<until&&!s.hero.Health.Dead){while(corner<path.corners.Length-1&&Vector3.ProjectOnPlane(path.corners[corner]-s.hero.transform.position,Vector3.up).magnitude<.6f)corner++;var delta=Vector3.ProjectOnPlane(path.corners[Mathf.Min(corner,path.corners.Length-1)]-s.hero.transform.position,Vector3.up);s.hero.GetComponent<CharacterController>().Move(Vector3.ClampMagnitude(delta,s.hero.moveSpeed*Time.deltaTime));if(Time.frameCount%20==0)Trace("actual-cc-move",from:start.position,to:end.position);yield return null;}yield return Wait(()=>Mathf.Abs(s.hero.transform.position.y-end.position.y)<.65f,1.5f);bool ok=Vector3.ProjectOnPlane(s.hero.transform.position-end.position,Vector3.up).magnitude<.7f&&Mathf.Abs(s.hero.transform.position.y-end.position.y)<.65f;Check("physical-walk-"+goal,ok,"NavMesh corners + actual CharacterController.Move; no teleport");if(!ok){var c=s.hero.GetComponent<CharacterController>();var lo=s.hero.transform.position+c.center-Vector3.up*(c.height/2-c.radius);var hi=lo+Vector3.up*(c.height-2*c.radius);File.AppendAllLines(Root+"/blocked-colliders.txt",Physics.OverlapCapsule(lo,hi,c.radius+.2f).Select(x=>x.name+" | "+x.bounds+" | "+x.transform.parent?.name));throw new Exception("Movement blocked before "+goal+" at "+s.hero.transform.posi