 string LootSignature()=>string.Join("|",UnityEngine.Object.FindObjectsByType<LootPickup>(FindObjectsSortMode.None).Where(l=>l.gameObject.scene==s.gameObject.scene&&!l.Collected).OrderBy(l=>l.InteractionId).Select(l=>l.InteractionId+":"+l.Amount+":"+l.Kind+":"+l.Gear?.id));
