 string TerrainSignature(){using(var sha=System.Security.Cryptography.SHA256.Create())using(var ms=new MemoryStream()){foreach(var t in s.GetComponent<ForestRegionRuntime>().PresentationRoot.GetComponentsInChildren<Terrain>().OrderBy(t=>t.transform.position.z).ThenBy(t=>t.transform.position.x)){var h=t.terrainData.GetHeights(0,0,257,257);var b=new byte[h.Length*4];Buffer.BlockCopy(h,0,b,0,b.Length);ms.Write(b,0,b.Length);var holes=t.terrainData.GetHoles(0,0,256,256);foreach(bool present in holes)ms.WriteByte(present?(byte)1:(byte)0);}return BitConverter.ToString(sha.ComputeHash(ms.ToArray())).Replace("-","");}}
 string Ledger(){var r=s.Flow.ActiveRun;return string.Join(",",r.broughtRemaining)+"|"+string.Join(",",r.earnedRemaining)+"|"+string.Join(",",s.Camp.Materials)+"|"+string.Join(",",s.Flow.Profile.badges.OrderBy(x=>x))+"|"+JsonUtility.ToJson(s.Flow.Profile.tutorial);}
