  bool lethalObserved=false;enemy.Health.Observed+=o=>Trace("enemy-health",enemy.entityId,o.before,o.after);h.Health.Observed+=o=>{Trace("hero-health",enemy.entityId,o.before,o.after);if(o.before>0&&o.after<=0)lethalObserved=true;};c.MeleeObserved+=o=>Trace("actual-melee-"+o.reason,o.target?.name,o.before,o.after);c.NewWeapons.Observed+=o=>Trace("new-weapon-"+o.stage,o.target?.name,o.before,o.after,o.a,o.b);c.Expanded.Observed+=o=>Trace("expanded-skill-"+o.stage,o.target?.name,o.before,o.after,o.origin,o.direction);AdventureProjectile.Observed+=Projectile;
