  IEnumerator PrepareCamp(){foreach(var type in new[]{GearType.TwinBlades,GearType.Greatsword,GearType.Scythe})yield return Equip(type);var owned=s.hero.GetComponent<AdventureLoadout>().items.Concat(s.Camp.Items).Where(i=>i.Weapon).Select(i=>i.type).Distinct().OrderBy(i=>(int)i).ToArray();Check("camp-all-seven-owned",owned.SequenceEqual(new[]{GearType.Sword,GearType.Spear,GearType.Staff,GearType.Bow,GearType.TwinBlades,GearType.Greatsword,GearType.Scythe}));Check("camp-real-save",s.Saves.SaveProgress(false));Check("camp-real-reload",s.Saves.LoadProgress(false));yield return null;Check("camp-owned-after-load",s.hero.GetComponent<AdventureLoadout>().items.Concat(s.Camp.Items).Where(i=>i.Weapon).Select(i=>i.type).Distinct().Count()==7);string dest=Root+"/CampPackage";Directory.CreateDirectory(dest);foreach(var file in Directory.GetFiles(Path.GetDirectoryName(s.Saves.SavePath),"*",SearchOption.AllDirectories)){string rel=file.Substring(Path.GetDirectoryName(s.Saves.SavePath).Length).TrimStart(Path.DirectorySeparatorChar);string target=Path.Combine(dest,rel);Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(file,target,false);}File.WriteAllText(Root+"/camp-fixture.json","{\"scope\":\"Synthetic gear was created only as explicit test input, acquired by real LootPickup, warehoused and saved by real camp transactions. Not earned gameplay evidence. Profile contains all seven weapons for optional human testing.\"}");}
  IEnumerator AssistProof(){yield return Equip(GearType.Sword);yield return Depart();var enemy=s.enemies.Single(e=>e.entityId=="c1:guard");FreezeOthers(enemy);yield return Go(new Vector3(-4.5f,.1f,195));var h=s.hero;var combat=h.GetComponent<AdventureCombat>();s.orbit.enabled=false;var camera=s.orbit.GetComponent<Camera>();float stop=Time.realtimeSinceStartup+10;while(Vector3.ProjectOnPlane(enemy.transform.position-h.transform.position,Vector3.up).magnitude>1.8f&&Time.realtimeSinceStartup<stop){h.GetComponent<CharacterController>().Move(Vector3.ProjectOnPlane(enemy.transform.position-h.transform.position,Vector3.up).normalized*h.moveSpeed*Time.deltaTime);yield return null;}camera.transform.position=h.transform.position+new Vector3(3,3,-5);camera.transform.LookAt(enemy.GetComponent<CharacterController>().bounds.center);PlayerInput.Focus(true);yield return null;string streams=JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams),global=JsonUtility.ToJson(UnityEngine.Random.state);combat.Assist.Clear();Check("c1-actual-target-selection",combat.Assist.Choose(MeleeGeometry.Center(h.transform.position),4,true)==enemy);Check("c1-target-query-readonly",streams==JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams)&&global==JsonUtility.ToJson(UnityEngine.Random.state));var column=new Vector3(-12,0,196);var target=enemy.GetComponent<CharacterController>().bounds.center;var away=Vector3.ProjectOnPlane(column-target,Vector3.up).normalized;camera.transform.position=column+away*2+Vector3.up*1.1f;camera.transform.LookAt(target);combat.Assist.Clear();bool blocked=Physics.Linecast(camera.transform.position,target,out var hit,~0,QueryTriggerInteraction.Ignore);Check("c1-actual-column-first-occluder",blocked&&hit.collider.name=="猫族十棱石柱",hit.collider?.name);Check("c1-column-rejects-soft-target",combat.Assist.Choose(combat.MuzzlePosition,60)==null);Trace("assist-column-ray",hit.collider?.name,from:camera.transform.position,to:target);camera.transform.position=h.transform.position+new Vector3(