 IEnumerator Run(){yield return Entry();if(mode=="assist"){yield return AssistProof();yield break;}if(mode=="prepare-camp"){yield return PrepareCamp();yield break;}if(mode=="fault"){yield return Depart();yield return Faults();yield break;}if(mode=="resume-frontier"){yield return FrontierResume();yield break;}if(mode=="resume"){yield return Resume();yield break;}if(mode.StartsWith("combat-")){yield return Combat((GearType)int.Parse(mode.Substring(7)));yield break;}if(mode=="elite"){yield return Combat(GearType.Spear,false,false,true);yield break;}if(mode=="boss"){yield return Combat(GearType.Sword,true);yield break;}if(mode=="death"){yield return Combat(GearType.Sword,false,true);yield break;}yield return Depart();yield return Explore();}
